heck(zero.TestingScalarResidual(stationary_scalar)==0.0,"zero-layer stationary scalar residual");for(std::size_t i=0;i<zero_scalar.band_node_ids.size();++i)Check(!std::memcmp(&zero_scalar.band_values[i],&stationary_scalar[stationary.al.LocalNode(zero_scalar.band_node_ids[i])],sizeof(double)),"zero-layer stationary scalar band bits");for(std::size_t i=0;i<zero_scalar.target_node_ids.size();++i)Check(!std::memcmp(&zero_scalar.target_values[i],&stationary_scalar[stationary.al.LocalNode(zero_scalar.target_node_ids[i])],sizeof(double)),"zero-layer stationary scalar target bits");auto zero_again=ImmersedVelocityExtension::Build(*stationary.a,stationary.al,stationary_state,*stationary.b,stationary.bl,0);auto zero_scalar_again=zero_again.ExtendScalar(stationary_scalar);Check(zero.HashSha256()==zero_again.HashSha256()&&zero.OperatorHashSha256()==zero_again.OperatorHashSha256()&&zero.ReducedHashSha256()==zero_again.ReducedHashSha256()&&zero_scalar.hash_sha256==zero_scalar_retry.hash_sha256&&zero_scalar.hash_sha256==zero_scalar_again.hash_sha256&&Bits(zero_scalar.band_values,zero_scalar_retry.band_values)&&Bits(zero_scalar.band_values,zero_scalar_again.band_values)&&Bits(zero_scalar.target_values,zero_scalar_retry.target_values)&&Bits(zero_scalar.target_values,zero_scalar_again.target_values),"zero-layer stationary determinism");
